```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Neon Flight</title>
<style>
  body { margin: 0; overflow: hidden; background: #050510; color: white; font-family: sans-serif; }
  canvas { display: block; }
  #ui { position: absolute; top: 10px; left: 10px; z-index: 10; pointer-events: none; }
  #score { font-size: 24px; font-weight: bold; text-shadow: 0 0 5px #0ff; }
  #gameover { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); text-align: center; display: none; z-index: 20; }
  h1 { font-size: 48px; margin: 0 0 20px 0; text-shadow: 0 0 10px #f0f; }
  button { background: #0ff; border: none; padding: 10px 20px; font-size: 20px; cursor: pointer; font-weight: bold; border-radius: 5px; box-shadow: 0 0 10px #0ff; pointer-events: auto; color: #000; }
  button:hover { background: #fff; }
</style>
</head>
<body>
<div id="ui"><div id="score">Score: 0</div></div>
<div id="gameover">
  <h1>GAME OVER</h1>
  <button onclick="resetGame()">RESTART</button>
</div>
<canvas id="gameCanvas"></canvas>
<script>
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  let score = 0, gameOver = false, frame = 0;
  const keys = {};
  window.addEventListener('keydown', e => keys[e.code] = true);
  window.addEventListener('keyup', e => keys[e.code] = false);

  class Player {
    constructor() {
      this.width = 30; this.height = 40;
      this.x = canvas.width / 2; this.y = canvas.height - 100;
      this.speed = 8; this.cooldown = 0;
    }
    update() {
      if (keys['ArrowLeft'] || keys['KeyA']) this.x -= this.speed;
      if (keys['ArrowRight'] || keys['KeyD']) this.x += this.speed;
      if (keys['ArrowUp'] || keys['KeyW']) this.y -= this.speed;
      if (keys['ArrowDown'] || keys['KeyS']) this.y += this.speed;

      this.x = Math.max(this.width/2, Math.min(canvas.width - this.width/2, this.x));
      this.y = Math.max(this.height/2, Math.min(canvas.height - this.height/2, this.y));

      if ((keys['Space'] || keys['Enter'] || keys['KeyJ']) && this.cooldown <= 0) {
        bullets.push(new Bullet(this.x, this.y - this.height/2));
        this.cooldown = 8;
      }
      if (this.cooldown > 0) this.cooldown--;
    }
    draw() {
      ctx.save(); ctx.translate(this.x, this.y);
      ctx.fillStyle = '#0ff'; ctx.shadowBlur = 15; ctx.shadowColor = '#0ff';
      ctx.beginPath(); ctx.moveTo(0, -this.height/2); ctx.lineTo(this.width/2, this.height/2);
      ctx.lineTo(0, this.height/4); ctx.lineTo(-this.width/2, this.height/2);
      ctx.closePath(); ctx.fill(); ctx.restore();
    }
  }

  class Bullet {
    constructor(x, y) { this.x = x; this.y = y; this.speed = 18; this.radius = 4; this.marked = false; }
    update() { this.y -= this.speed; if (this.y < 0) this.marked = true; }
    draw() {
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = '#fff'; ctx.fill();
    }
  }

  class Enemy {
    constructor() {
      this.width = 40; this.height = 40;
      this.x = Math.random() * (canvas.width - this.width) + this.width/2;
      this.y = -this.height;
      this.speed = Math.random() * 4 + 2;
      this.marked = false; this.hp = 2;
    }
    update() { this.y += this.speed; if (this.y > canvas.height + this.height) this.marked = true; }
    draw() {
      ctx.save(); ctx.translate(this.x, this.y);
      ctx.fillStyle = '#f0f'; ctx.shadowBlur = 15; ctx.shadowColor = '#f0f';
      ctx.beginPath(); ctx.moveTo(0, this.height/2); ctx.lineTo(this.width/2, -this.height/2);
      ctx.lineTo(-this.width/2, -this.height/2);
      ctx.closePath(); ctx.fill(); ctx.restore();
    }
  }

  class Particle {
    constructor(x, y, color) {
      this.x = x; this.y = y;
      this.vx = (Math.random() - 0.5) * 12; this.vy = (Math.random() - 0.5) * 12;
      this.life = 1; this.color = color;
    }
    update() { this.x += this.vx; this.y += this.vy; this.life -= 0.04; }
    draw() {
      ctx.globalAlpha = Math.max(0, this.life); ctx.fillStyle = this.color;
      ctx.fillRect(this.x, this.y, 5, 5); ctx.globalAlpha = 1;
    }
  }

  class Star {
    constructor() {
      this.x = Math.random() * canvas.width; this.y = Math.random() * canvas.height;
      this.speed = Math.random() * 3 + 0.5; this.size = Math.random() * 2 + 1;
    }
    update() { this.y += this.speed; if (this.y > canvas.height) { this.y = 0; this.x = Math.random() * canvas.width; } }
    draw() { ctx.fillStyle = 'rgba(255, 255, 255, 0.6)'; ctx.fillRect(this.x, this.y, this.size, this.size); }
  }

  let player = new Player(), bullets = [], enemies = [], particles = [], stars = Array(150).fill().map(() => new Star());

  function createExplosion(x, y, color) { for (let i = 0; i < 25; i++) particles.push(new Particle(x, y, color)); }

  function checkCollisions() {
    enemies.forEach(enemy => {
      bullets.forEach(bullet => {
        let dx = bullet.x - enemy.x, dy = bullet.y - enemy.y;
        if (Math.sqrt(dx*dx + dy*dy) < enemy.width/2 + bullet.radius) {
          bullet.marked = true; enemy.hp--;
          if (enemy.hp <= 0) {
            enemy.marked = true; score += 10; document.getElementById('score').innerText = `Score: ${score}`;
            createExplosion(enemy.x, enemy.y, '#f0f');
          } else { createExplosion(bullet.x, bullet.y, '#fff'); }
        }
      });
      let dx = player.x - enemy.x, dy = player.y - enemy.y;
      if (Math.sqrt(dx*dx + dy*dy) < enemy.width/2 + player.width/2 - 8) {
        gameOver = true; createExplosion(player.x, player.y, '#0ff');
        document.getElementById('gameover').style.display = 'block';
      }
    });
  }

  function animate() {
    if (gameOver) return;
    ctx.fillStyle = 'rgba(5, 5, 16, 0.4)'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    stars.forEach(s => { s.update(); s.draw(); });
    player.update(); player.draw();
    if (frame % 30 === 0) enemies.push(new Enemy());
    bullets.forEach(b => { b.update(); b.draw(); });
    enemies.forEach(e => { e.update(); e.draw(); });
    particles.forEach(p => { p.update(); p.draw(); });
    bullets = bullets.filter(b => !b.marked); enemies = enemies.filter(e => !e.marked); particles = particles.filter(p => p.life > 0);
    checkCollisions(); frame++; requestAnimationFrame(animate);
  }

  window.resetGame = () => {
    player = new Player(); bullets = []; enemies = []; particles = []; score = 0; frame = 0; gameOver = false;
    document.getElementById('score').innerText = `Score: 0`; document.getElementById('gameover').style.display = 'none'; animate();
  };
  window.addEventListener('resize', () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; });
  animate();
</script>
</body>
</html>

